UPDATE user
SET user_nick_name = #{userNickName},
    email = #{email},
    phone = #{phone},
    description = #{description}
WHERE user_name = #{userName}

mapper.select:
SELECT user_name, user_nick_name, email, phone, description
FROM user
WHERE user_name = #{userName}
